import React, { useState } from 'react';

const ChatbotPage = () => {
  const [userInput, setUserInput] = useState("");
  const [chatResponse, setChatResponse] = useState(""); // To store chatbot replies

  const sendMessage = async () => {
    if (!userInput.trim()) return; // Prevent sending empty messages

    try {
      const response = await fetch("http://10.100.19.64:5000/api/chat", {  
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: userInput }),
      });

      const data = await response.json();
      setChatResponse(data.reply); // Display chatbot response
    } catch (error) {
      console.error("Error sending message:", error);
      setChatResponse("⚠️ Unable to connect to chatbot!");
    }
  };

  return (
    <div className="chatbot-page">
      <h1>Chatbot</h1>
      <input
        type="text"
        placeholder="Type a message..."
        value={userInput}
        onChange={(e) => setUserInput(e.target.value)}
        onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
      />
      <button className="pink-button" onClick={sendMessage}>
        Send
      </button>
      {chatResponse && <p className="chat-response">{chatResponse}</p>}
    </div>
  );
};

export default ChatbotPage;
